{
  "name": "lucasp-claude-plugins",
  "owner": {
    "name": "Lucas Pimentel"
  },
  "metadata": {
    "description": "Personal Claude Code plugins by Lucas Pimentel",
    "pluginRoot": "./plugins"
  },
  "plugins": [
    {
      "name": "lucas-dev-tools",
      "source": "./plugins/lucas-dev-tools",
      "description": "Developer workflow utilities: git commits, PR reviews, PR comments, docs updates, clipboard helpers",
      "version": "1.2.4"
    },
    {
      "name": "windows-notify",
      "source": "./plugins/windows-notify",
      "description": "Shows Windows toast notifications when Claude Code needs attention",
      "version": "1.2.1"
    },
    {
      "name": "chezmoi",
      "source": "./plugins/chezmoi",
      "description": "Chezmoi dotfile management: diff resolution, file sync between source and destination",
      "version": "1.0.4"
    },
    {
      "name": "windows-terminal",
      "source": "./plugins/windows-terminal",
      "description": "Windows Terminal pane and tab management via wt.exe",
      "version": "1.1.0"
    },
    {
      "name": "linters",
      "source": "./plugins/linters",
      "description": "Runs linters on edited files: cslint (.cs), PSScriptAnalyzer (.ps1), shellcheck (.sh)",
      "version": "1.0.0"
    }
  ]
}
